const input = $json.body || $json;
function clean(s){ return String(s ?? '').replace(/\r/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{4,}/g,'\n\n\n').trim(); }
const url = clean(input.url || '');
const title = clean(input.title || 'TryHackMe Room');
const selection = clean(input.selection || '');
const visibleText = clean(input.text || input.content || '');
const sourceText = selection || visibleText;
if (!sourceText || sourceText.length < 30) throw new Error('No llegó texto suficiente desde la room. Abre la room, espera a que cargue o selecciona una tarea concreta y vuelve a ejecutar la extensión.');
const maxChars = 65000;
const clipped = sourceText.slice(0, maxChars);
const wasClipped = sourceText.length > maxChars;
const prompt = `Eres un traductor técnico para laboratorios de ciberseguridad como TryHackMe y pwn.college.

OBJETIVO:
Crear una versión en castellano entendible del lab/sala/challenge, manteniendo todos los tecnicismos de ciberseguridad en inglés tal como aparecen en el texto original.

REGLAS OBLIGATORIAS:
- Traduce al castellano de España las explicaciones, instrucciones y descripciones.
- Mantén EN INGLÉS y sin modificar tecnicismos como: enumeration, reconnaissance, reverse shell, bind shell, payload, exploit, vulnerability, privilege escalation, hash, brute force, wordlist, flag, CTF, scan, port, service, endpoint, shell, listener, exploit, foothold, pivoting, SQL injection, XSS, SSRF, LFI, RFI, command injection, credentials, token, cookie, session, request, response, header, API, Docker, Linux, Windows, Active Directory, SMB, Kerberos, LDAP, DNS, HTTP, HTTPS, SSH, FTP, Nmap, Gobuster, Burp Suite, Metasploit, Hydra, John, Hashcat, Wireshark y nombres de herramientas.
- Mantén exactamente comandos, código, rutas, IPs, puertos, hashes, URLs, flags, nombres de ficheros, parámetros y opciones CLI.
- No resuelvas el lab, sala ni challenge.
- No respondas preguntas del laboratorio.
- No inventes pasos, comandos, flags ni soluciones que no estén en el texto original.
- Si aparece una pregunta tipo “What is...?” o un challenge de pwn.college, tradúcelo pero NO lo contestes ni indiques solución.
- Añade explicaciones breves en español SOLO para entender conceptos técnicos presentes en el texto; no añadas procedimiento de resolución.
- Conserva estructura por títulos, tareas, listas y bloques.

FORMATO DE SALIDA:
Devuelve Markdown limpio en español:
# ${title}

**Enlace original:** ${url || 'capturado desde navegador'}

## Versión traducida
...

## Conceptos técnicos mantenidos en inglés
- Término en inglés: explicación breve en español, solo si aparece en el texto.

## Nota de seguridad
Traducción educativa. No incluye resolución, flags, exploits añadidos ni respuestas.

CONTENIDO ORIGINAL:
---
${clipped}
---
${wasClipped ? '\nNota interna: el texto fue recortado por longitud. Indica al final que puede faltar parte de la room y que el usuario puede seleccionar un bloque concreto para continuar.' : ''}`;
return [{ json: { chatId: $env.TELEGRAM_CHAT_ID, url, title, chars: sourceText.length, wasClipped, prompt } }];

