const prep = $('Preparar prompt técnico').first().json;
const translation = $json.choices?.[0]?.message?.content || $json.body?.choices?.[0]?.message?.content || 'No se pudo extraer la traducción.';
function esc(v){ return String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function inline(s){ return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>'); }
function mdToHtml(md){
  const lines = String(md).split('\n');
  let html = '', inCode = false, code = [];
  for (const raw of lines) {
    const line = raw.replace(/\s+$/,'');
    if (line.startsWith('```')) { if (!inCode){ inCode=true; code=[]; } else { html += `<pre><code>${esc(code.join('\n'))}</code></pre>`; inCode=false; } continue; }
    if (inCode) { code.push(line); continue; }
    if (/^# /.test(line)) html += `<h1>${inline(line.replace(/^# /,''))}</h1>`;
    else if (/^## /.test(line)) html += `<h2>${inline(line.replace(/^## /,''))}</h2>`;
    else if (/^### /.test(line)) html += `<h3>${inline(line.replace(/^### /,''))}</h3>`;
    else if (/^[-*] /.test(line)) html += `<li>${inline(line.replace(/^[-*] /,''))}</li>`;
    else if (/^\d+\. /.test(line)) html += `<li>${inline(line.replace(/^\d+\. /,''))}</li>`;
    else if (!line.trim()) html += '<br>';
    else html += `<p>${inline(line)}</p>`;
  }
  if (inCode) html += `<pre><code>${esc(code.join('\n'))}</code></pre>`;
  return html;
}
const now = new Date().toISOString().replace(/[:.]/g,'-').slice(0,19);
const safeTitle = String(prep.title || 'tryhackme-room').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70) || 'tryhackme-room';
const fileName = `cyber-lab-es-tecnico-${safeTitle}-${now}.html`;
const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(prep.title)} · Lab ES técnico</title><style>
:root{--bg:#06100b;--panel:#0b1811;--text:#eafff0;--muted:#9bcfaf;--green:#37ff8b;--cyan:#69f7ff;--line:rgba(55,255,139,.35)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,rgba(55,255,139,.12),transparent 26%),var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;line-height:1.62}.wrap{max-width:980px;margin:auto;padding:18px}.card{border:1px solid var(--line);background:linear-gradient(180deg,rgba(11,24,17,.98),rgba(3,8,5,.98));border-radius:20px;padding:20px;box-shadow:0 18px 60px rgba(0,0,0,.35)}.meta{color:var(--muted);font-size:14px;border-bottom:1px dashed var(--line);padding-bottom:12px}h1,h2,h3{color:var(--green);line-height:1.18}h1{font-size:clamp(28px,6vw,48px)}h2{margin-top:28px}a{color:var(--cyan)}code,pre{background:#020403;border:1px solid #214d34;border-radius:8px;color:#dcffe8}code{padding:2px 5px}pre{overflow:auto;padding:12px}li{margin:6px 0}.warn{border-left:4px solid #ffd166;background:#251f0b;color:#ffe7a6;padding:10px 12px;border-radius:10px;margin:12px 0}.footer{color:var(--muted);font-size:12px;margin-top:22px}</style></head><body><main class="wrap"><section class="card"><p class="meta"><b>Cyber Lab Translator</b> · castellano con tecnicismos en inglés · no resuelve labs/challenges<br><b>URL:</b> ${esc(prep.url || 'capturada desde navegador')}<br><b>Caracteres capturados:</b> ${esc(prep.chars)}</p>${prep.wasClipped ? '<div class="warn">La room era larga y se tradujo la primera parte capturada. Selecciona un bloque concreto para continuar con el resto.</div>' : ''}${mdToHtml(translation)}<p class="footer">Generado por Ara/Hermes vía n8n · Traducción educativa sin resolución, flags ni respuestas añadidas.</p></section></main></body></html>`;
return [{ json: { chatId: prep.chatId, fileName, caption: `Lab traducido al español técnico: ${prep.title}`.slice(0,1000), ok:true, title:prep.title, url:prep.url }, binary: { data: { data: Buffer.from(html,'utf8').toString('base64'), mimeType:'text/html', fileName, fileExtension:'html' } } }];
